Method.Source:
 //URL design property need is getting assigned. 
[FormDesignPropertyAttribute("URL", "URL")]
 public str parmURL(str _URL = URL)
 {
     if (!prmIsDefault(_URL))
     {
         URL = _URL;
     }
     return URL;
 }
